import{_ as p,a0 as o,w as d,s as r,ao as l,I as t,x as n,a1 as e,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"如何在 Linux 上使用網絡配置工具 Netplan | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 上使用網絡配置工具 Netplan | LCTT (201810) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 上使用網絡配置工具 Netplan | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 上使用網絡配置工具 Netplan | LCTT (201810) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201810/20180907 How to Use the Netplan Network Configuration Tool on Linux","title":"如何在 Linux 上使用網絡配置工具 Netplan","tag":"201810","desc":""},"relativePath":"201810/20180907 How to Use the Netplan Network Configuration Tool on Linux.md","filePath":"[post].md"}'),h={name:"201810/20180907 How to Use the Netplan Network Configuration Tool on Linux.md"};function u(g,s,k,c,b,f){const a=o("Link");return d(),r("div",null,[s[25]||(s[25]=l(`<h1 id="如何在-linux-上使用網絡配置工具-netplan" tabindex="-1">如何在 Linux 上使用網絡配置工具 Netplan <a class="header-anchor" href="#如何在-linux-上使用網絡配置工具-netplan" aria-label="Permalink to “如何在 Linux 上使用網絡配置工具 Netplan”">​</a></h1><blockquote><p>netplan 是一個命令列工具，用於在某些 Linux 發行版上配置網絡。</p></blockquote><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/netplan.jpg?itok=Gu_ZfNGa" alt=""></p><p>多年以來 Linux 管理員和用户們以相同的方式配置他們的網絡接口。例如，如果你是 Ubuntu 用户，你能夠用桌面 GUI 配置網絡連接，也可以在 <code>/etc/network/interfaces</code> 文件裏配置。配置相當簡單且可以奏效。在文件中配置看起來就像這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>auto enp10s0</span></span>
<span class="line"><span>iface enp10s0 inet static</span></span>
<span class="line"><span>address 192.168.1.162</span></span>
<span class="line"><span>netmask 255.255.255.0</span></span>
<span class="line"><span>gateway 192.168.1.100</span></span>
<span class="line"><span>dns-nameservers 1.0.0.1,1.1.1.1</span></span></code></pre></div><p>保存並關閉文件。使用命令重啓網絡：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo systemctl restart networking</span></span></code></pre></div><p>或者，如果你使用不帶 systemd 的發行版，你可以通過老辦法來重啓網絡：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo /etc/init.d/networking restart</span></span></code></pre></div><p>你的網絡將會重新啓動，新的配置將會生效。</p>`,10)),t("p",null,[s[1]||(s[1]=n("這就是多年以來的做法。但是現在，在某些發行版上（例如 Ubuntu Linux 18.04），網絡的配置與控制發生了很大的變化。不需要那個 ",-1)),s[2]||(s[2]=t("code",null,"interfaces",-1)),s[3]||(s[3]=n(" 文件和 ",-1)),s[4]||(s[4]=t("code",null,"/etc/init.d/networking",-1)),s[5]||(s[5]=n(" 腳本，我們現在轉向使用 ",-1)),e(a,{href:"https://netplan.io/"},{default:i(()=>[...s[0]||(s[0]=[n("Netplan",-1)])]),_:1}),s[6]||(s[6]=n("。Netplan 是一個在某些 Linux 發行版上配置網絡連接的命令列工具。Netplan 使用 YAML 描述文件來配置網絡接口，然後，通過這些描述為任何給定的呈現工具生成必要的配置選項。",-1))]),s[26]||(s[26]=l(`<p>我將向你展示如何在 Linux 上使用 Netplan 配置靜態 IP 地址和 DHCP 地址。我會在 Ubuntu Server 18.04 上演示。有句忠告，你創建的 .yaml 文件中的縮進必須保持一致，否則將會失敗。你不用為每行使用特定的縮進間距，只需保持一致就行了。</p><h3 id="新的配置文件" tabindex="-1">新的配置文件 <a class="header-anchor" href="#新的配置文件" aria-label="Permalink to “新的配置文件”">​</a></h3><p>打開終端窗口（或者通過 SSH 登錄進 Ubuntu 服務器）。你會在 <code>/etc/netplan</code> 文件夾下發現 Netplan 的新配置文件。使用 <code>cd /etc/netplan</code> 命令進入到那個文件夾下。一旦進到了那個文件夾，也許你就能夠看到一個文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>01-netcfg.yaml</span></span></code></pre></div><p>你可以創建一個新的文件或者是編輯默認文件。如果你打算修改默認文件，我建議你先做一個備份：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo cp /etc/netplan/01-netcfg.yaml /etc/netplan/01-netcfg.yaml.bak</span></span></code></pre></div><p>備份好後，就可以開始配置了。</p><h3 id="網絡設備名稱" tabindex="-1">網絡設備名稱 <a class="header-anchor" href="#網絡設備名稱" aria-label="Permalink to “網絡設備名稱”">​</a></h3><p>在你開始配置靜態 IP 之前，你需要知道設備名稱。要做到這一點，你可以使用命令 <code>ip a</code>，然後找出哪一個設備將會被用到（圖 1）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/netplan_1.jpg?itok=XuIsXWbV" alt="netplan" title="netplan"></p><p><em>圖 1：使用 ip a 命令找出設備名稱</em></p><p>我將為 ens5 配置一個靜態的 IP。</p><h3 id="配置靜態-ip-地址" tabindex="-1">配置靜態 IP 地址 <a class="header-anchor" href="#配置靜態-ip-地址" aria-label="Permalink to “配置靜態 IP 地址”">​</a></h3><p>使用命令打開原來的 .yaml 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo nano /etc/netplan/01-netcfg.yaml</span></span></code></pre></div><p>文件的佈局看起來就像這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>network:</span></span>
<span class="line"><span>    Version: 2</span></span>
<span class="line"><span>    Renderer: networkd</span></span>
<span class="line"><span>    ethernets:</span></span>
<span class="line"><span>       DEVICE_NAME:</span></span>
<span class="line"><span>          Dhcp4: yes/no</span></span>
<span class="line"><span>          Addresses: [IP/NETMASK]</span></span>
<span class="line"><span>          Gateway: GATEWAY</span></span>
<span class="line"><span>          Nameservers:</span></span>
<span class="line"><span>             Addresses: [NAMESERVER, NAMESERVER]</span></span></code></pre></div><p>其中：</p><ul><li><code>DEVICE_NAME</code> 是需要配置設備的實際名稱。</li><li><code>yes</code>/<code>no</code> 代表是否啓用 dhcp4。</li><li><code>IP</code> 是設備的 IP 地址。</li><li><code>NETMASK</code> 是 IP 地址的掩碼。</li><li><code>GATEWAY</code> 是網關的地址。</li><li><code>NAMESERVER</code> 是由逗號分開的 DNS 服務器列表。</li></ul><p>這是一份 .yaml 文件的樣例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>network:</span></span>
<span class="line"><span>    version: 2</span></span>
<span class="line"><span>    renderer: networkd</span></span>
<span class="line"><span>    ethernets:</span></span>
<span class="line"><span>       ens5:</span></span>
<span class="line"><span>       dhcp4: no</span></span>
<span class="line"><span>       addresses: [192.168.1.230/24]</span></span>
<span class="line"><span>       gateway4: 192.168.1.254</span></span>
<span class="line"><span>       nameservers:</span></span>
<span class="line"><span>          addresses: [8.8.4.4,8.8.8.8]</span></span></code></pre></div><p>編輯上面的文件以達到你想要的效果。保存並關閉文件。</p><p>注意，掩碼已經不用再配置為 <code>255.255.255.0</code> 這種形式。取而代之的是，掩碼已被添加進了 IP 地址中。</p><h3 id="測試配置" tabindex="-1">測試配置 <a class="header-anchor" href="#測試配置" aria-label="Permalink to “測試配置”">​</a></h3><p>在應用改變之前，讓我們測試一下配置。為此，使用命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo netplan try</span></span></code></pre></div><p>上面的命令會在應用配置之前驗證其是否有效。如果成功，你就會看到配置被接受。換句話説，Netplan 會嘗試將新的配置應用到運行的系統上。如果新的配置失敗了，Netplan 會自動地恢復到之前使用的配置。成功後，新的配置就會被使用。</p><h3 id="應用新的配置" tabindex="-1">應用新的配置 <a class="header-anchor" href="#應用新的配置" aria-label="Permalink to “應用新的配置”">​</a></h3><p>如果你確信配置文件沒有問題，你就可以跳過測試環節並且直接使用新的配置。它的命令是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo netplan apply</span></span></code></pre></div><p>此時，你可以使用 ip a 看看新的地址是否正確。</p><h3 id="配置-dhcp" tabindex="-1">配置 DHCP <a class="header-anchor" href="#配置-dhcp" aria-label="Permalink to “配置 DHCP”">​</a></h3><p>雖然你可能不會配置 DHCP 服務，但通常還是知道比較好。例如，你也許不知道網絡上當前可用的靜態 IP 地址是多少。你可以為設備配置 DHCP，獲取到 IP 地址，然後將那個地址重新配置為靜態地址。</p><p>在 Netplan 上使用 DHCP，配置文件看起來就像這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>network:</span></span>
<span class="line"><span>    version: 2</span></span>
<span class="line"><span>    renderer: networkd</span></span>
<span class="line"><span>    ethernets:</span></span>
<span class="line"><span>       ens5:</span></span>
<span class="line"><span>       Addresses: []</span></span>
<span class="line"><span>       dhcp4: true</span></span>
<span class="line"><span>       optional: true</span></span></code></pre></div><p>保存並退出。用下面命令來測試文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo netplan try</span></span></code></pre></div><p>Netplan 應該會成功配置 DHCP 服務。這時你可以使用 <code>ip a</code> 命令得到動態分配的地址，然後重新配置靜態地址。或者，你可以直接使用 DHCP 分配的地址（但看看這是一個服務器，你可能不想這樣做）。</p><p>也許你有不只一個的網絡接口，你可以命名第二個 .yaml 文件為 <code>02-netcfg.yaml</code> 。Netplan 會按照數字順序應用配置文件，因此 01 會在 02 之前使用。根據你的需要創建多個配置文件。</p><h3 id="就是這些了" tabindex="-1">就是這些了 <a class="header-anchor" href="#就是這些了" aria-label="Permalink to “就是這些了”">​</a></h3><p>不管怎樣，那些就是所有關於使用 Netplan 的東西了。雖然它對於我們習慣性的配置網絡地址來説是一個相當大的改變，但並不是所有人都用的慣。但這種配置方式值得一提……因此你會適應的。</p>`,41)),t("p",null,[s[8]||(s[8]=n("在 Linux Foundation 和 edX 上通過 ",-1)),e(a,{href:"https://training.linuxfoundation.org/linux-courses/system-administration-training/introduction-to-linux"},{default:i(()=>[...s[7]||(s[7]=[n("“Introduction to Linux”",-1)])]),_:1}),s[9]||(s[9]=n(" 課程學習更多關於 Linux 的內容。",-1))]),s[27]||(s[27]=t("hr",null,null,-1)),t("p",null,[s[11]||(s[11]=n("via: ",-1)),e(a,{href:"https://www.linux.com/learn/intro-to-linux/2018/9/how-use-netplan-network-configuration-tool-linux"},{default:i(()=>[...s[10]||(s[10]=[n("https://www.linux.com/learn/intro-to-linux/2018/9/how-use-netplan-network-configuration-tool-linux",-1)])]),_:1})]),t("p",null,[s[16]||(s[16]=n("作者：",-1)),e(a,{href:"https://www.linux.com/users/jlwallen"},{default:i(()=>[...s[12]||(s[12]=[n("Jack Wallen",-1)])]),_:1}),s[17]||(s[17]=n(" 選題：",-1)),e(a,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[13]||(s[13]=[n("lujun9972",-1)])]),_:1}),s[18]||(s[18]=n(" 譯者：",-1)),e(a,{href:"https://github.com/LuuMing"},{default:i(()=>[...s[14]||(s[14]=[n("LuuMing",-1)])]),_:1}),s[19]||(s[19]=n(" 校對：",-1)),e(a,{href:"https://github.com/wxy"},{default:i(()=>[...s[15]||(s[15]=[n("wxy",-1)])]),_:1})]),t("p",null,[s[22]||(s[22]=n("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[20]||(s[20]=[n("LCTT",-1)])]),_:1}),s[23]||(s[23]=n(" 原創編譯，",-1)),e(a,{href:"https://linux.cn/"},{default:i(()=>[...s[21]||(s[21]=[n("Linux中國",-1)])]),_:1}),s[24]||(s[24]=n(" 榮譽推出",-1))])])}const C=p(h,[["render",u]]);export{y as __pageData,C as default};
